import 'package:cabina/common/theme/app_theme.dart';
import 'package:flutter/material.dart';

/// "Generated by AI" as a small tinted pill next to the sheet's title.
class AILabelChip extends StatelessWidget {
  const AILabelChip({super.key});

  @override
  Widget build(BuildContext context) {
    final theme = context.appTheme;
    return DecoratedBox(
      decoration: ShapeDecoration(
        shape: const StadiumBorder(),
        color: theme.foreground.withValues(alpha: 0.08),
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
        child: Text(
          'Generated by AI',
          style: AppTextStyles.caption.copyWith(color: theme.foregroundSoft),
        ),
      ),
    );
  }
}
